#!/usr/bin/env python3
"""Rebuild the English research whitepaper from verified paceval CSV and figures."""
from pathlib import Path
import csv, html, json
from reportlab.platypus import SimpleDocTemplate,Paragraph,Spacer,Image,Table,TableStyle,PageBreak,KeepTogether
from reportlab.lib.styles import getSampleStyleSheet,ParagraphStyle
from reportlab.lib.enums import TA_LEFT,TA_CENTER
from reportlab.lib.colors import HexColor,white
from reportlab.lib.pagesizes import A4
from reportlab.lib.units import mm
ROOT=Path(__file__).resolve().parent.parent
PDF=ROOT/'paceval_Extreme_Analytic_Terrain_Whitepaper_EN.pdf'
rows=list(csv.DictReader((ROOT/'results'/'execution_summary.csv').open()))
mesh=json.loads((ROOT/'results'/'mesh_validation.json').read_text())
BLUE=HexColor('#183653');TEAL=HexColor('#177f84');INK=HexColor('#263c51');LIGHT=HexColor('#e9f1f5')
styles=getSampleStyleSheet()
styles.add(ParagraphStyle(name='HeroTitleX',fontName='Helvetica-Bold',fontSize=22,leading=27,textColor=BLUE,spaceAfter=12))
styles.add(ParagraphStyle(name='H1X',fontName='Helvetica-Bold',fontSize=16,leading=20,textColor=BLUE,spaceBefore=4,spaceAfter=12,keepWithNext=True))
styles.add(ParagraphStyle(name='H2X',fontName='Helvetica-Bold',fontSize=10.4,leading=14,textColor=TEAL,spaceBefore=11,spaceAfter=6,keepWithNext=True))
styles.add(ParagraphStyle(name='BodyX',fontName='Helvetica',fontSize=9.4,leading=14.2,textColor=INK,spaceAfter=9))
styles.add(ParagraphStyle(name='CaptionX',fontName='Helvetica-Oblique',fontSize=8,leading=11,textColor=INK,spaceAfter=9))
styles.add(ParagraphStyle(name='SmallX',fontName='Helvetica',fontSize=8,leading=12,textColor=INK,spaceAfter=6))
styles.add(ParagraphStyle(name='LeadX',fontName='Helvetica',fontSize=12,leading=17,textColor=INK,spaceAfter=12))
styles.add(ParagraphStyle(name='EqX',fontName='Courier',fontSize=8.3,leading=12,textColor=BLUE,spaceAfter=10,leftIndent=14))

D=SimpleDocTemplate(str(PDF),pagesize=A4,rightMargin=19*mm,leftMargin=19*mm,topMargin=19*mm,bottomMargin=18*mm,title='Extreme-Length Analytic Terrain Functions with paceval',author='paceval research demonstrator')
story=[]
def p(x,style='BodyX'):story.append(Paragraph(x,styles[style]))
def h(x):p(x,'H1X')
def sub(x):p(x,'H2X')
def img(path,w=168*mm,maxh=110*mm):
 from PIL import Image as PI
 pix=PI.open(ROOT/path);width,height=pix.size; hh=w*height/width
 if hh>maxh:w=w*maxh/hh;hh=maxh
 story.append(Image(str(ROOT/path),width=w,height=hh,hAlign='CENTER'))
def cap(s):p(s,'CaptionX')
def page():story.append(PageBreak())
def table(data,widths=None):
 t=Table([[Paragraph(str(q),styles['SmallX']) for q in row] for row in data],colWidths=widths,repeatRows=1,hAlign='LEFT')
 t.setStyle(TableStyle([('BACKGROUND',(0,0),(-1,0),BLUE),('TEXTCOLOR',(0,0),(-1,0),white),('ROWBACKGROUNDS',(0,1),(-1,-1),[white,LIGHT]),('VALIGN',(0,0),(-1,-1),'TOP'),('BOTTOMPADDING',(0,0),(-1,-1),7),('TOPPADDING',(0,0),(-1,-1),7)]))
 # reportlab Paragraph black text in dark header avoided via separate plain headers
 t._cellvalues[0]=[Paragraph('<font color="#ffffff">'+html.escape(str(q))+'</font>',styles['SmallX']) for q in data[0]]
 story.append(t);story.append(Spacer(1,7*mm))

def footer(canvas,doc):
 canvas.saveState();w,h=A4;canvas.setStrokeColor(HexColor('#b7d5da'));canvas.line(19*mm,15*mm,w-19*mm,15*mm);canvas.setFont('Helvetica',7);canvas.setFillColor(INK)
 canvas.drawString(19*mm,11*mm,'paceval | extreme analytic terrain research | 2026');canvas.drawRightString(w-19*mm,11*mm,str(doc.page));canvas.restoreState()

p('PACEVAL  |  SCIENTIFIC RESEARCH DEMONSTRATOR','SmallX')
p('Extreme-Length Analytic Terrain Functions with paceval','HeroTitleX')
p('Three reusable mathematical landscapes, real paceval execution, genuine GLB/OBJ terrain meshes and independently checked output.','LeadX')
img('figures/00_extreme_terrain_hero.png',maxh=86*mm)
cap('Concept illustration; not a computed research result. The following scientific figures are generated from actual paceval height grids.')
p('<b>Verified scope.</b> Three explicitly expanded formulas of 274,877, 412,381 and 550,086 characters were each created as a monolithic paceval computation and tested. Their mathematically equivalent 256-term subgraphs generated three 40 × 40 numerical terrain grids.')
p('<b>Scientific boundary.</b> These are synthetic 2.5D analytic height fields, not geological reconstructions, calibrated hydrological models or evidence of production rendering performance.')
page()
h('1. Industrial context and current state of the art')
p('Engineering visualization, geographic information systems, game production and industrial digital twins consume terrain surfaces at different resolutions. In operational geospatial workflows, elevation is generally represented using measured digital elevation models (DEMs), lidar-derived products, raster tiles or 3D scene assets. The USGS 3D Elevation Program defines relevant data products and metadata requirements [2].')
p('An alternative workflow stores an explicit mathematical surface as an editable asset. A downstream renderer evaluates this function at specified coordinates and triangulates the resulting heights. Such functions can be versioned and reused across visualization, verification and geometry export without editing a fixed raster asset.')
p('Procedural terrain is well established. Recent research includes analytic terrain evolution and erosion-aware models, which address geologic consistency beyond synthetic Gaussian features [1]. The OGC 3D Tiles standard defines scalable streaming of heterogeneous 3D geospatial content and uses glTF as a primary renderable format [3].')
sub('Concrete demonstration workflow')
p('A landscape author selects a mathematical scene definition, evaluates a deterministic coordinate grid using reusable paceval computation graphs, checks the numeric values and exports an actual triangulated GLB/OBJ scene. The host application handles graph composition, grid assembly, optional constant-level water geometry and mesh serialization; paceval evaluates the mathematical height expressions.')
sub('What this experiment tests')
p('The research question is whether a large, explicitly stored landscape formula can be parsed and reused by the actual paceval engine, and whether a mathematically equivalent graph decomposition can calculate complete height grids for several structurally distinct landscapes. A spatially realistic DEM fitting task is not part of this experiment.')
page()
h('2. Defined mathematical model')
p('Each scene is a scalar height function on normalized coordinates x,y in [-1,1], used as a 2.5D surface S(x,y) = (x,y,h(x,y)).')
p('h(x,y) = h_background(x,y) + sum(j=1..N) a_j * exp(-((x-cx_j)^2/sx_j + (y-cy_j)^2/sy_j))','EqX')
p('Here N is 2,048, 3,072 or 4,096. Each amplitude a_j, center cx_j/cy_j and positive width sx_j/sy_j is generated deterministically using a fixed SplitMix64 seed. Literal coefficients are serialized with 17 significant digits. All model coordinates and elevations are synthetic and dimensionless.')
p('The background terms are different by landscape: two mountains and a depression for Alpine Lake, a broad volcanic cone with a narrow summit depression for Volcanic Caldera, and low-frequency ridges with a diagonal incision for Canyon Ridges. The additional Gaussian terms provide fine-scale relief; increasing character count alone does not guarantee more realistic topography.')
sub('Actual expression lengths')
table([['Scene','Terms','Complete expression length'],*[ [r['scene'].replace('_',' ').title(),f"{int(r['terms']):,}",f"{int(r['formula_characters']):,} characters"] for r in rows]],[55*mm,30*mm,85*mm])
p('Each complete formula is saved, unabridged, in the expressions/ directory. These are genuine formulas, not padding text. Character counts exclude the final newline added by the file serializer.')
page()
h('3. Executed paceval architecture')
p('The program links the original paceval_main.h and paceval_main.cpp interface files to a compatible separately supplied Linux shared library. Each scene is first created as one complete monolithic expression using paceval_CreateComputation and executed at five test coordinates.')
p('For the spatially complete surface, the same formula is split into an unchanged background expression and blocks of 256 Gaussian terms. Each block is registered once as a reusable paceval computation handle. The host then calls paceval_dGetMultipleComputationsResultsExt on coordinate batches and sums the returned graph-major results for each position.')
sub('Real execution boundary')
table([['Execution property','Recorded result'],['Monolithic formula instances','3; five scalar test points per formula'],['Reusable graphs total','42; including all monolithic and grouped expressions'],['Computed height-field samples','4,800 across three 40 x 40 grids'],['Independent C++ spot checks','Selected positions from every evaluated grid'],['High-precision independent checks','9 checks using 55-digit mpmath'],['Mesh geometry','3 GLB scenes and corresponding terrain/water OBJ meshes']],[80*mm,90*mm])
p('The batch API produces height values. All file handling, terrain triangulation, colored illustration, water surfaces, data validation and GLB/OBJ serialization are performed by the host or offline visualization scripts, not by paceval.')
page()
h('4. Three distinct computed landscapes')
sub('4.1 Alpine lake and mountain relief')
img('figures/01_alpine_lake_surface.png',maxh=112*mm)
cap('Figure 1. Actual 40 x 40 paceval height field, 2,048 analytic Gaussian features and a designed basin.')
p('The height grid contains three connected geometric influences: a pair of broad mountain features, a negative depression and additional analytic microrelief. A constant-level water surface is constructed offline for below-water cells. It does not simulate water flow or infer drainage.')
page()
h('4.2 Volcanic caldera')
img('figures/03_volcanic_caldera_surface.png',maxh=112*mm)
cap('Figure 2. Actual 40 x 40 paceval height field, 3,072 features and a raised ring-like synthetic caldera.')
p('The volcanic model includes a large positive mound, a narrow negative central feature and oscillatory terrain detail. It is an analytic geometric representation, not an eruption, geomechanics or lava-flow model.')
page()
h('4.3 Canyon and ridge system')
img('figures/05_canyon_ridges_surface.png',maxh=112*mm)
cap('Figure 3. Actual 40 x 40 paceval height field, 4,096 features with a diagonal erosional-looking incision.')
p('A ridge and canyon shape is encoded directly as a closed-form expression. No sediment transport or physical incision law is solved. The export preserves the mathematical output as an inspectable 3D surface.')
page()
h('5. Terrain contours and water-level geometry')
p('Contour maps provide a 2D check that important topographic features are present in the actual computed data. Blue contours mark declared constant water levels; they are not predictions of physically stable water bodies.')
img('figures/02_alpine_lake_contours.png',maxh=87*mm)
cap('Figure 4. Alpine height contours derived directly from paceval results.')
img('figures/04_volcanic_caldera_contours.png',maxh=87*mm)
cap('Figure 5. Caldera contours and synthetic water-level crossing.')
page()
h('6. Canyon contours and exported geometry')
img('figures/06_canyon_ridges_contours.png',maxh=108*mm)
cap('Figure 6. Contours of the actual canyon-ridge mathematical surface and a declared illustrative level.')
p('Every 40 x 40 terrain grid produces 1,600 vertices and 3,042 triangles. The separately exported water meshes are made of constant-height triangles over cells with all four corners below the water threshold. This simple construction is not a connected-basin hydrology algorithm and must not be interpreted as a correctly clipped or physically validated shoreline.')
p('GLB scene files were reloaded with trimesh, and the presence of nonempty triangle geometry was verified. The output is 2.5D: it has no caves, overhangs or volumetric strata.')
page()
h('7. Explicit expression scale and verification')
img('figures/07_verified_formula_lengths.png',maxh=85*mm)
cap('Figure 7. Verified expression lengths from the executed C++/paceval run, not projected or simulated limits.')
p('All three full expressions were successfully created as individual computation graphs. Sampled monolithic evaluation and complete grouped evaluation passed the predeclared numerical verification checks. Nine independent high-precision spot checks were executed using a separately implemented Python coefficient generator.')
sub('What “no fixed formula-length limit” means')
p('paceval describes no predefined product-level limit on expression length, subject to hardware and development-environment resources [4,5]. This is not a proof that arbitrary-length formulas can always be executed. In particular, one billion characters would require sufficient memory for the source string, parsing, graph representation, evaluation buffers and practical compute resources, and it has NOT been tested in this research.')
p('The largest <b>actually tested complete formula</b> in this new experiment is 550,086 characters. The attached source whitepaper reports a separate prior test reaching 3,032,517 characters with 16,384 terms. The present report does not repeat or reclassify that earlier test as a newly executed result.')
page()
h('8. Research interpretation and next steps')
p('The significant demonstrated capability is management and execution of very large editable mathematical landscape expressions, including exact formula export, repeated graph evaluation, independent numeric checking and genuine 3D geometry extraction. This does not demonstrate any CPU, GPU, energy or end-to-end rendering advantage over alternative terrain algorithms.')
sub('Meaningful industrial follow-up')
p('To evaluate geospatial relevance, fit the analytic basis to a public digital elevation tile, preserve coordinate reference systems and vertical datums, use spatially held-out test blocks and compare elevation, slope, curvature and hydrological connectivity. For a production digital twin, integrate level-of-detail, tiling and data provenance. For physically meaningful landscape formation, couple the mathematical function to an erosion/hydrology solver rather than treating visual shapes as physics.')
sub('Reproduction')
p('Configure CMake against a compatible separately acquired paceval Linux runtime. Run the executable with --out . --grid 40, then run the independent high-precision script and scientific figure/mesh generator. Exact build commands and a verified file inventory are documented in the root README.md. No restricted shared-library binary is redistributed.')
sub('References')
p('[1] Physically-based analytical erosion for fast terrain generation (2024), Computer Graphics Forum. doi:10.1111/cgf.15033.','SmallX')
p('[2] USGS 3D Elevation Program standards: https://www.usgs.gov/ngp-standards-and-specifications/3d-elevation-program-standards-and-specifications','SmallX')
p('[3] OGC 3D Tiles 1.1: https://www.ogc.org/standards/3DTiles/','SmallX')
p('[4] paceval Product Brief: https://paceval.com/product-brief/','SmallX')
p('[5] paceval API and C/C++ interface: https://paceval.com/api/','SmallX')
p('Conclusion. Three new terrain expressions of more than 250,000 characters each were generated, parsed and independently evaluated with the real paceval engine; their calculated heights produced three verifiable 3D terrain scenes. Claims for larger untested formulas remain conditional on available hardware and software resources.','BodyX')
D.build(story,onFirstPage=footer,onLaterPages=footer)
print('created',PDF)
